DROP TABLE IF EXISTS `race_state`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `race_state` (
  `state_id` int NOT NULL AUTO_INCREMENT,
  `session_id` int NOT NULL,
  `driver_id` int NOT NULL,
  `lap_number` int NOT NULL,
  `position` int DEFAULT NULL,
  `gap_ahead_s` float DEFAULT NULL,
  `gap_behind_s` float DEFAULT NULL,
  `closing_rate_ahead_s_per_lap` float DEFAULT NULL,
  `energy_start_mj` float DEFAULT NULL,
  `energy_deployed_mj` float DEFAULT NULL,
  `energy_harvested_mj` float DEFAULT NULL,
  `energy_end_mj` float DEFAULT NULL,
  `attack_opportunity` tinyint(1) DEFAULT '0',
  PRIMARY KEY (`state_id`),
  KEY `driver_id` (`driver_id`),
  KEY `idx_race_state_session_driver_lap` (`session_id`,`driver_id`,`lap_number`),
  CONSTRAINT `race_state_ibfk_1` FOREIGN KEY (`session_id`) REFERENCES `sessions` (`session_id`),
  CONSTRAINT `race_state_ibfk_2` FOREIGN KEY (`driver_id`) REFERENCES `drivers` (`driver_id`)
) ENGINE=InnoDB AUTO_INCREMENT=1981 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
